Here's a complete p5.js sketch. Paste it into the [p5.js web editor](https://editor.p5js.org/) and press play.

```javascript
let flashStart = -1;            // when the flash began (-1 = not flashing)
const FLASH_DURATION = 2000;    // 2 seconds
const FLASH_INTERVAL = 100;     // ms between color swaps

function setup() {
  createCanvas(400, 500);

  const btn = createButton('Flash Eyes');
  btn.mousePressed(() => {
    flashStart = millis();
  });
}

function draw() {
  background(225, 240, 255);

  drawAntenna();
  drawLegs();
  drawBody();
  drawArms();
  drawHead();
  drawEyes();
  drawMouth();
}

function isFlashing() {
  return flashStart >= 0 && millis() - flashStart < FLASH_DURATION;
}

function drawAntenna() {
  stroke(80);
  strokeWeight(4);
  line(200, 60, 200, 92);
  noStroke();
  fill(255, 60, 60);
  ellipse(200, 52, 22, 22);
}

function drawHead() {
  stroke(40);
  strokeWeight(3);
  fill(90, 140, 210);
  rect(140, 90, 120, 100, 15);

  // ears
  fill(250, 190, 50);
  rect(125, 125, 15, 30, 4);
  rect(260, 125, 15, 30, 4);

  // neck
  fill(120);
  rect(188, 190, 24, 16);
}

function drawEyes() {
  let eyeColor, pupilColor;

  if (isFlashing()) {
    // alternate colors every FLASH_INTERVAL ms
    const on = floor((millis() - flashStart) / FLASH_INTERVAL) % 2 === 0;
    eyeColor = on ? color(255, 255, 0) : color(255, 40, 40);
    pupilColor = on ? color(255, 120, 0) : color(255, 255, 255);

    // glow
    noStroke();
    fill(red(eyeColor), green(eyeColor), blue(eyeColor), 90);
    ellipse(175, 130, 50, 50);
    ellipse(225, 130, 50, 50);
  } else {
    eyeColor = color(255);
    pupilColor = color(30, 30, 30);
  }

  stroke(40);
  strokeWeight(3);
  fill(eyeColor);
  ellipse(175, 130, 32, 32);
  ellipse(225, 130, 32, 32);

  noStroke();
  fill(pupilColor);
  ellipse(175, 130, 14, 14);
  ellipse(225, 130, 14, 14);
}

function drawMouth() {
  stroke(40);
  strokeWeight(3);
  fill(50);
  rect(170, 160, 60, 18, 4);

  // teeth
  stroke(255);
  strokeWeight(2);
  for (let x = 180; x < 230; x += 10) {
    line(x, 160, x, 178);
  }
}

function drawBody() {
  stroke(40);
  strokeWeight(3);
  fill(220, 90, 90);
  rect(130, 206, 140, 150, 20);

  // control panel
  fill(40);
  rect(155, 230, 90, 60, 8);

  noStroke();
  fill(80, 220, 120);
  ellipse(175, 250, 16, 16);
  fill(255, 220, 60);
  ellipse(200, 250, 16, 16);
  fill(100, 180, 255);
  ellipse(225, 250, 16, 16);

  // belt
  stroke(40);
  strokeWeight(3);
  fill(250, 190, 50);
  rect(130, 325, 140, 20);
}

function drawArms() {
  stroke(40);
  strokeWeight(3);

  // upper arms
  fill(120, 200, 140);
  rect(90, 215, 32, 100, 12);
  rect(278, 215, 32, 100, 12);

  // hands
  fill(250, 190, 50);
  ellipse(106, 325, 40, 40);
  ellipse(294, 325, 40, 40);

  // shoulder joints
  fill(150);
  ellipse(122, 222, 22, 22);
  ellipse(278, 222, 22, 22);
}

function drawLegs() {
  stroke(40);
  strokeWeight(3);

  // legs
  fill(120, 200, 140);
  rect(155, 355, 35, 90, 8);
  rect(210, 355, 35, 90, 8);

  // feet
  fill(90, 90, 160);
  rect(140, 445, 60, 26, 10);
  rect(200, 445, 60, 26, 10);
}
```

**How it works**
- **Button:** `createButton('Flash Eyes')` adds an HTML button below the canvas. When pressed, it stores the current time in `flashStart`.
- **2-second flash:** `isFlashing()` returns `true` while less than 2000 ms have passed since `flashStart`.
- **Flashing effect:** During the flash, the eyes swap between yellow/red every 100 ms and get a translucent glow. Afterward they return to white with dark pupils.

You can adjust `FLASH_DURATION` and `FLASH_INTERVAL` at the top to change the length and speed of the flash.

