  fill(80, 80, 100);
  rect(135, 440, 60, 22, 8);
  rect(205, 440, 60, 22, 8);

  // --- Arms ---
  fill(120, 120, 140);
  rect(85, 215, 35, 100, 10);   // left arm
  rect(280, 215, 35, 100, 10);  // right arm

  // Hands
  fill(255, 200, 0);
  circle(102, 325, 32);
  circle(298, 325, 32);

  // --- Body ---
  fill(255, 140, 50);
  rect(130, 205, 140, 150, 12);

  // Chest panel
  fill(50, 50, 70);
  rect(155, 225, 90, 60, 8);

  // Panel buttons
  noStroke();
  fill(255, 60, 60);
  circle(175, 245, 14);
  fill(60, 220, 100);
  circle(200, 245, 14);
  fill(70, 140, 255);
  circle(225, 245, 14);

  // Panel bar
  fill(255, 255, 100);
  rect(165, 265, 70, 10, 3);
  stroke(40);
  strokeWeight(3);

  // --- Neck ---
  fill(100, 100, 120);
  rect(188, 188, 24, 20);

  // --- Antenna ---
  line(200, 60, 200, 90);
  fill(255, 50, 50);
  circle(200, 52, 18);

  // --- Head ---
  fill(100, 180, 240);
  rect(140, 90, 120, 100, 15);

  // --- Eyes ---
  drawEyes();

  // --- Mouth ---
  fill(40);
  rect(165, 158, 70, 20, 5);
  stroke(255);
  strokeWeight(2);
  line(177, 158, 177, 178);
  line(188, 158, 188, 178);
  line(200, 158, 200, 178);
  line(212, 158, 212, 178);
  line(223, 158, 223, 178);
}

function drawEyes() {
  let eyeColor = color(255);
  let pupilColor = color(30);
  let glow = false;

  if (flashing) {
    const elapsed = millis() - flashStart;

    if (elapsed >= FLASH_DURATION) {
      flashing = false;
    } else {
      // Alternate between bright and dark every FLASH_INTERVAL ms
      const on = floor(elapsed / FLASH_INTERVAL) % 2 === 0;
      if (on) {
        eyeColor = color(255, 255, 0);   // bright yellow
        pupilColor = color(255, 0, 0);   // red pupil
        glow = true;
      } else {
        eyeColor = color(60);
        pupilColor = color(0);
      }
    }
  }

  // Glow effect
  if (glow) {
    noStroke();
    fill(255, 255, 0, 80);
    circle(175, 125, 50);
    circle(225, 125, 50);
  }

  stroke(40);
  strokeWeight(3);
  fill(eyeColor);
  circle(175, 125, 30);
  circle(225, 125, 30);

  noStroke();
  fill(pupilColor);
  circle(175, 125, 12);
  circle(225, 125, 12);
}
```

**How it works**
- **Robot parts:** Everything is drawn with `rect()`, `circle()`, and `line()`. The legs, arms, and body are drawn before the head so the overlaps look right.
- **Colors:** The head is blue, the body orange, the limbs gray, the hands yellow, and the chest panel has red, green, and blue lights.
- **Button:** `createButton()` makes an HTML button below the canvas, and `mousePressed(startFlash)` runs `startFlash()` when it's clicked. That function records the time with `millis()` and sets `flashing = true`.
- **2-second flash:** While `flashing` is true, `drawEyes()` checks the elapsed time. It toggles the eyes between bright yellow with a glow and dark every 100 ms, then stops after 2000 ms.

You can change `FLASH_DURATION` or `FLASH_INTERVAL` at the top to adjust how long and how fast the eyes flash.

